  ok('global freeze lifted; A→B 10 and B→A 10 both succeed (balances unchanged)')

  step('Ban C')
  const ban = await issuer.ban(C.classicAddress, 'Demo: sanctions screening hit')
  assert.equal(ban.clawedBack, '100')
